import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.DuPBmefI.js";const h=JSON.parse('{"title":"基督教崇真中学 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-8519ff16","school_zh":"基督教崇真中学","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"基督教崇真中学 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-TTCA-2021"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-8519ff16/s1/2020-21-interview.md","filePath":"reports/school-8519ff16/s1/2020-21-interview.md"}'),a={name:"reports/school-8519ff16/s1/2020-21-interview.md"};function n(p,o,c,l,i,d){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="基督教崇真中学-·-2020-21年度-·-中一-·-面试" tabindex="-1">基督教崇真中学 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#基督教崇真中学-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;基督教崇真中学 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-8519ff16">← 返回基督教崇真中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-ttca-2021" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ttca-2021" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ttca-2021}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>三科口答与场地</strong></p><p>多组反馈整体约30至40分钟，三位老师分科，学生口头作答。有场次在饭堂内同时进行多组一对一，考生感觉嘈杂。数学有人面对纸题、有人用iPad，不把全部场次归为同一种媒介。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语</p><p><strong>理解与词语运用</strong></p><p>介绍原校、同学老师怎样看自己；阅读后答文章类型、主旨、修辞和启示，找“懦弱”的两个反义词，一个从文中找、一个自己想。用“十万火急”“人山人海”“三心两意”造句，并辨认形近字。</p><p><strong>图片与经历表达</strong></p><p>两幅图讲故事，或看男孩先赞一女孩漂亮、再勉强赞另一女孩的图片发表看法；另一图为两人在有冷气的室内读书，一人说热，代入另一人回应。短讲主题有受伤、帮助别人、学校旅行的经历与感受。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>介绍、朗读与语法</strong></p><p>自我介绍及追问、推荐英文书、朗读文章；不同考生有纯朗读或另问理解。选择题考词汇、时态、in/on/at、if句型及情境回应，例如怎样接受下周生日会邀请；另问星期三与星期五之间是哪一天、学校应有哪些设施。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>题量和时长版本</strong></p><p>有人6分钟心算且不准纸笔；有人约10题，或10分钟约12题；另有4分钟10题。均保留为不同反馈，不平均成统一时限。</p><p><strong>运算范围</strong></p><p>分数除法、小数乘法、四则运算、应用题、立体图形、方向、近似值及取值至万位。部分考生感觉题目较深、需要答得快。</p></blockquote>',12)])])}const _=t(a,[["render",n]]);export{h as __pageData,_ as default};
